	import sailpoint.object.ResourceObject;
	import org.apache.log4j.Logger;

	Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
	if (logger.isTraceEnabled()) {
		logger.trace("Entered to Alpha-Rule-ResourceObjectCustomization-AppraisalSoft!!!");
	}
	if (object.getObjectType().compareTo(Connector.TYPE_ACCOUNT) == 0) {
		logger.debug("Alpha-Rule-ResourceObjectCustomization-AppraisalSoft -> ResourceObject : " +object.toXml());
		String status = (String)object.getAttribute("Status");

		if (status.equals("0")) {
			object.put("Status","Active");
		}
		else {
			object.put("Status","Inactive");
		}
	}
	if (logger.isTraceEnabled()) {
		logger.trace("Alpha-Rule-ResourceObjectCustomization-AppraisalSoft Ended!!!");
	}
	return object;
